<?php require_once __DIR__.'/../includes/auth.php';role('superadmin','shop_admin','staff');header('Content-Type:application/json');function calc($p,$a,$n){$r=$a/1200;return $r?($p*$r*pow(1+$r,$n)/(pow(1+$r,$n)-1)):$p/$n;}$p=(float)($_REQUEST['principal']??0);$a=(float)($_REQUEST['rate']??18);$o=[];foreach([6,12,18,24] as $n){$m=calc($p,$a,$n);$o[]=['tenure'=>$n,'emi'=>round($m,2),'interest'=>round($m*$n-$p,2),'total'=>round($m*$n,2)];}echo json_encode(['success'=>true,'options'=>$o]);
